import { Project } from '../../domain/project/Project';
import { ProjectRepository } from '../../domain/project/ProjectRepository';
import { ProjectDto, toProjectDto } from '../dto/ProjectDto';
import { IdGenerator } from '../ports/IdGenerator';
import { CreateProjectInput, CreateProjectUseCase } from './CreateProjectUseCase';

export class CreateProjectService implements CreateProjectUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: CreateProjectInput): Promise<ProjectDto> {
    const project = Project.create(this.ids.next(), input.name);
    await this.projects.save(project);
    return toProjectDto(project);
  }
}

=====SOURCE-END=====

