import { ProjectRepository } from '../../domain/project/ProjectRepository';
import { ProjectDto, toProjectDto } from '../dto/ProjectDto';
import { ListProjectsUseCase } from './ListProjectsUseCase';

export class ListProjectsService implements ListProjectsUseCase {
  constructor(private readonly projects: ProjectRepository) {}

  async execute(): Promise<ProjectDto[]> {
    const projects = await this.projects.findAll();
    return projects.map(toProjectDto);
  }
}

